import { Accordion as AccordionPrimitive } from "@ark-ui/vue/accordion";
import { PhCaretDown } from "@phosphor-icons/vue";
import { accordionItemRecipe } from "@pisagor/recipes/accordion";
import { defineComponent, h, type PropType, type VNodeChild } from "vue";
import type { ClassValue } from "../../internal/types";

// #region Types
export interface AccordionPresetItem {
  value: string;
  title: VNodeChild;
  content: VNodeChild;
  disabled?: boolean;
}

export interface AccordionProps {
  items?: AccordionPresetItem[];
  collapsible?: boolean;
  lazyMount?: boolean;
  unmountOnExit?: boolean;
}

export interface AccordionItemProps {
  /**
   * Style recipe. Defaults to `accordionItemRecipe` from `@pisagor/recipes/accordion-item`.
   *
   * @defaultValue accordionItemRecipe
   */
  itemRecipe?: typeof accordionItemRecipe;
  class?: unknown;
}
// #endregion

// Ark Vue parts are polymorphic; `h()` overloads reject attr spreads without a cast.
type ArkPart = Parameters<typeof h>[0];

// #region Parts
export const AccordionRoot = defineComponent({
  inheritAttrs: false,
  name: "AccordionRoot",
  props: {
    collapsible: { default: true, type: Boolean },
    lazyMount: { default: true, type: Boolean },
    unmountOnExit: { default: true, type: Boolean },
  },
  setup(props, { attrs, slots }) {
    return () =>
      h(
        AccordionPrimitive.Root as ArkPart,
        {
          ...attrs,
          collapsible: props.collapsible,
          lazyMount: props.lazyMount,
          unmountOnExit: props.unmountOnExit,
        },
        slots,
      );
  },
});

export const AccordionItem = defineComponent({
  inheritAttrs: false,
  name: "AccordionItem",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
    itemRecipe: {
      default: accordionItemRecipe,
      type: Function as PropType<typeof accordionItemRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const variantSlots = props.itemRecipe();

      return h(
        AccordionPrimitive.Item as ArkPart,
        {
          ...attrs,
          class: variantSlots.base({ class: props.class }),
        },
        slots,
      );
    };
  },
});

export const AccordionItemTrigger = defineComponent({
  inheritAttrs: false,
  name: "AccordionItemTrigger",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
    itemRecipe: {
      default: accordionItemRecipe,
      type: Function as PropType<typeof accordionItemRecipe>,
    },
  },
  setup(props, { attrs, slots: children }) {
    return () => {
      const variantSlots = props.itemRecipe();

      return h(
        AccordionPrimitive.ItemTrigger as ArkPart,
        {
          ...attrs,
          class: variantSlots.trigger({ class: props.class }),
        },
        () => [
          children.default?.(),
          h(AccordionPrimitive.ItemIndicator as ArkPart, {}, () =>
            h(PhCaretDown, { class: variantSlots.indicator() }),
          ),
        ],
      );
    };
  },
});

export const AccordionItemContent = defineComponent({
  inheritAttrs: false,
  name: "AccordionItemContent",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
    itemRecipe: {
      default: accordionItemRecipe,
      type: Function as PropType<typeof accordionItemRecipe>,
    },
  },
  setup(props, { attrs, slots: children }) {
    return () => {
      const variantSlots = props.itemRecipe();

      return h(
        AccordionPrimitive.ItemContent as ArkPart,
        {
          ...attrs,
          class: variantSlots.content({ class: props.class }),
        },
        () => h("div", { class: variantSlots.body() }, children.default?.()),
      );
    };
  },
});

export const AccordionShorthand = defineComponent({
  inheritAttrs: false,
  name: "AccordionShorthand",
  props: {
    collapsible: { default: true, type: Boolean },
    items: { default: undefined, type: Array as PropType<AccordionPresetItem[]> },
    lazyMount: { default: true, type: Boolean },
    unmountOnExit: { default: true, type: Boolean },
  },
  setup(props, { attrs }) {
    return () =>
      h(
        AccordionRoot,
        {
          ...attrs,
          collapsible: props.collapsible,
          lazyMount: props.lazyMount,
          unmountOnExit: props.unmountOnExit,
        },
        () =>
          props.items?.map((item) =>
            h(
              AccordionItem,
              { disabled: item.disabled, key: item.value, value: item.value },
              () => [
                h(AccordionItemTrigger, null, () => item.title),
                h(AccordionItemContent, null, () => item.content),
              ],
            ),
          ),
      );
  },
});
// #endregion

import {
  AccordionItem,
  AccordionItemContent,
  AccordionItemTrigger,
  AccordionRoot,
  AccordionShorthand,
} from "./accordion";

export type { AccordionPresetItem, AccordionProps } from "./accordion";

export const Accordion = Object.assign(AccordionShorthand, {
  Item: AccordionItem,
  ItemContent: AccordionItemContent,
  ItemTrigger: AccordionItemTrigger,
  Root: AccordionRoot,
});

import { ark } from "@ark-ui/vue/factory";
import { PhX } from "@phosphor-icons/vue";
import { type ActionBarRecipe, actionBarRecipe } from "@pisagor/recipes/action-bar";
import { cn } from "@pisagor/utils";
import {
  defineComponent,
  h,
  onBeforeUnmount,
  onMounted,
  type PropType,
  reactive,
  Teleport,
  type VNodeChild,
  watchEffect,
} from "vue";
import type { ClassValue } from "../../internal/types";
import { createContext } from "../../internal/utils/create-context";
import { Badge, type BadgeProps } from "../badge";
import { Button } from "../button";
import { Separator, type SeparatorProps } from "../separator";

type ArkPart = Parameters<typeof h>[0];

// #region Types
type ActionBarPlacement = "bottom" | "bottom-start" | "bottom-end";

interface ActionBarPositioning {
  gutter?: string;
  placement?: ActionBarPlacement;
}

interface ActionBarActionItem {
  icon?: VNodeChild;
  label: string;
  onClick: () => void;
  disabled?: boolean;
}

export interface ActionBarProps extends Pick<ActionBarContextValue, "lazyMount" | "unmountOnExit"> {
  closeOnEscape?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  open?: boolean;
  positioning?: ActionBarPositioning;
  count?: number;
  actions?: ActionBarActionItem[];
}

export interface ActionBarTriggerProps {
  onClick?: (event: MouseEvent) => void;
}

export interface ActionBarContentProps {
  /**
   * Style recipe. Defaults to `actionBarRecipe` from `@pisagor/recipes/action-bar`.
   *
   * @defaultValue actionBarRecipe
   */
  recipe?: typeof actionBarRecipe;
  class?: unknown;
  "aria-labelledby"?: string;
}

export interface ActionBarSeparatorProps extends SeparatorProps {}

export interface ActionBarCloseProps {
  onClick?: (event: MouseEvent) => void;
  class?: unknown;
}

export interface ActionBarValueProps
  extends Pick<BadgeProps, "class" | "pill" | "size" | "variant"> {
  count: number;
  label?: string;
  children?: VNodeChild;
}

interface ActionBarContextValue {
  isOpen?: boolean;
  lazyMount?: boolean;
  unmountOnExit?: boolean;
  onClose?: () => void;
  onOpen?: () => void;
  positioning: Required<ActionBarPositioning>;
  slots: ActionBarRecipe;
}
// #endregion

// #region Context
const [provideActionBarContext, useActionBarContext] = createContext<ActionBarContextValue>({
  name: "ActionBar",
  strict: false,
});
// #endregion

// #region Constants
const defaultPositioning: Required<ActionBarPositioning> = { gutter: "16px", placement: "bottom" };

function actionBarTeleport(content: ReturnType<typeof h> | ReturnType<typeof h>[]) {
  return h(Teleport, { to: "body" }, () => content);
}
// #endregion

// #region Parts
export const ActionBarRoot = defineComponent({
  inheritAttrs: false,
  name: "ActionBarRoot",
  props: {
    actions: { default: undefined, type: Array as PropType<ActionBarActionItem[]> },
    closeOnEscape: { default: true, type: Boolean },
    count: { default: undefined, type: Number },
    defaultOpen: { default: false, type: Boolean },
    lazyMount: { default: true, type: Boolean },
    onOpenChange: { default: undefined, type: Function as PropType<(open: boolean) => void> },
    open: { default: undefined, type: Boolean },
    positioning: { default: undefined, type: Object as PropType<ActionBarPositioning> },
    recipe: {
      default: actionBarRecipe,
      type: Function as PropType<typeof actionBarRecipe>,
    },
    unmountOnExit: { default: true, type: Boolean },
  },
  setup(props, { attrs, slots }) {
    const internalOpen = reactive<{ value: boolean }>({ value: props.defaultOpen });

    const isControlled = () => props.open !== undefined;
    const isOpen = () => (isControlled() ? props.open : internalOpen.value) ?? false;

    const handleClose = () => {
      if (!isControlled()) internalOpen.value = false;
      props.onOpenChange?.(false);
    };

    const handleOpen = () => {
      if (!isControlled()) internalOpen.value = true;
      props.onOpenChange?.(true);
    };

    let onKeyDown: ((event: KeyboardEvent) => void) | undefined;

    onMounted(() => {
      onKeyDown = (event) => {
        if (event.defaultPrevented) return;
        if (event.key !== "Escape") return;
        if (isOpen() && props.closeOnEscape) {
          event.preventDefault();
          handleClose();
        }
      };

      window.addEventListener("keydown", onKeyDown);
    });

    onBeforeUnmount(() => {
      if (onKeyDown) window.removeEventListener("keydown", onKeyDown);
    });

    const contextValue = reactive<ActionBarContextValue>({
      isOpen: isOpen(),
      lazyMount: props.lazyMount,
      onClose: handleClose,
      onOpen: handleOpen,
      positioning: { ...defaultPositioning, ...(props.positioning ?? {}) },
      slots: props.recipe(),
      unmountOnExit: props.unmountOnExit,
    });

    watchEffect(() => {
      contextValue.isOpen = isOpen();
      contextValue.lazyMount = props.lazyMount;
      contextValue.unmountOnExit = props.unmountOnExit;
      contextValue.positioning = { ...defaultPositioning, ...(props.positioning ?? {}) };
    });

    provideActionBarContext(contextValue);

    return () => {
      const hasPreset =
        props.count !== undefined || (props.actions !== undefined && props.actions.length > 0);

      return h(
        "div",
        {
          ...attrs,
          "data-part": "root",
          "data-scope": "action-bar",
        },
        () => [
          slots.default?.(),
          hasPreset
            ? h(ActionBarContent, null, () => [
                props.count !== undefined ? h(ActionBarValue, { count: props.count }) : null,
                props.count !== undefined ? h(ActionBarSeparator) : null,
                props.actions?.length
                  ? h(ActionBarBody, null, () =>
                      props.actions?.map((action) =>
                        h(
                          Button,
                          {
                            disabled: action.disabled,
                            key: action.label,
                            onClick: action.onClick,
                            size: "sm",
                            variant: "ghost",
                          },
                          () => [action.icon, action.label],
                        ),
                      ),
                    )
                  : null,
                props.actions?.length ? h(ActionBarSeparator) : null,
                h(ActionBarClose, null, () => h(PhX, { "aria-hidden": true })),
              ])
            : null,
        ],
      );
    };
  },
});

export const ActionBarTrigger = defineComponent({
  inheritAttrs: false,
  name: "ActionBarTrigger",
  props: {
    onClick: { default: undefined, type: Function as PropType<(event: MouseEvent) => void> },
  },
  setup(props, { attrs, slots }) {
    const context = useActionBarContext();

    return () => {
      return h(
        ark.button as unknown as ArkPart,
        {
          ...attrs,
          "aria-expanded": context?.isOpen ? "true" : "false",
          class: cn(attrs.class),
          "data-part": "trigger",
          "data-scope": "action-bar",
          "data-state": context?.isOpen ? "open" : "closed",
          onClick: (event: MouseEvent) => {
            context?.onOpen?.();
            props.onClick?.(event);
          },
          type: "button",
        },
        slots.default?.(),
      );
    };
  },
});

export const ActionBarContent = defineComponent({
  inheritAttrs: false,
  name: "ActionBarContent",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
  },
  setup(props, { attrs, slots }) {
    const context = useActionBarContext();

    return () => {
      if (!context) return null;

      const { placement, gutter } = context.positioning;

      if (!context.isOpen && context.unmountOnExit) {
        return null;
      }

      return actionBarTeleport(
        h(
          "div",
          {
            class: cn(context.slots.positioner({ placement })),
            "data-part": "positioner",
            "data-placement": placement,
            "data-scope": "action-bar",
            style: { "--gutter": gutter } as Record<string, unknown>,
          },
          () =>
            h(
              ark.div as unknown as ArkPart,
              {
                ...attrs,
                class: cn(context.slots.content(), props.class, attrs.class),
                "data-part": "content",
                "data-scope": "action-bar",
                role: "toolbar",
              },
              slots.default?.(),
            ),
        ),
      );
    };
  },
});

export const ActionBarSeparator = defineComponent({
  inheritAttrs: false,
  name: "ActionBarSeparator",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
    orientation: { default: "vertical", type: String as PropType<"horizontal" | "vertical"> },
    recipe: {
      default: actionBarRecipe,
      type: Function as PropType<typeof actionBarRecipe>,
    },
  },
  setup(props, { attrs }) {
    const context = useActionBarContext();

    return () =>
      h(
        Separator as ArkPart,
        {
          ...attrs,
          class: cn((context?.slots ?? props.recipe()).separator(), props.class, attrs.class),
          dataPart: "separator",
          dataScope: "action-bar",
          orientation: "vertical",
        },
        undefined,
      );
  },
});

export const ActionBarClose = defineComponent({
  inheritAttrs: false,
  name: "ActionBarClose",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
    onClick: { default: undefined, type: Function as PropType<(event: MouseEvent) => void> },
    recipe: {
      default: actionBarRecipe,
      type: Function as PropType<typeof actionBarRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    const context = useActionBarContext();

    return () => {
      return h(
        ark.button as unknown as ArkPart,
        {
          ...attrs,
          class: cn((context?.slots ?? props.recipe()).close(), props.class, attrs.class),
          "data-part": "close",
          "data-scope": "action-bar",
          "data-state": context?.isOpen ? "open" : "closed",
          onClick: (event: MouseEvent) => {
            context?.onClose?.();
            props.onClick?.(event);
          },
          type: "button",
        },
        slots.default?.(),
      );
    };
  },
});

export const ActionBarValue = defineComponent({
  inheritAttrs: false,
  name: "ActionBarValue",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
    count: { required: true, type: Number },
    label: { default: undefined, type: String },
    recipe: {
      default: actionBarRecipe,
      type: Function as PropType<typeof actionBarRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    const context = useActionBarContext();

    return () =>
      h(
        Badge as ArkPart,
        {
          ...attrs,
          class: cn((context?.slots ?? props.recipe()).value(), props.class, attrs.class),
          "data-part": "value",
          "data-scope": "action-bar",
          variant: "secondary",
        },
        () => slots.default?.() ?? props.label ?? props.count,
      );
  },
});

export const ActionBarBody = defineComponent({
  inheritAttrs: false,
  name: "ActionBarBody",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
    recipe: {
      default: actionBarRecipe,
      type: Function as PropType<typeof actionBarRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    const context = useActionBarContext();

    return () =>
      h(
        ark.div as unknown as ArkPart,
        {
          ...attrs,
          class: cn((context?.slots ?? props.recipe()).body(), props.class, attrs.class),
        },
        slots.default?.(),
      );
  },
});
// #endregion

import {
  ActionBarBody,
  ActionBarClose,
  ActionBarContent,
  ActionBarRoot,
  ActionBarSeparator,
  ActionBarTrigger,
  ActionBarValue,
} from "./action-bar";

export type {
  ActionBarCloseProps,
  ActionBarContentProps,
  ActionBarProps,
  ActionBarSeparatorProps,
  ActionBarTriggerProps,
  ActionBarValueProps,
} from "./action-bar";

export const ActionBar = Object.assign(ActionBarRoot, {
  Body: ActionBarBody,
  Close: ActionBarClose,
  Content: ActionBarContent,
  Separator: ActionBarSeparator,
  Trigger: ActionBarTrigger,
  Value: ActionBarValue,
});

import { ark } from "@ark-ui/vue/factory";
import {
  type AlertRecipe,
  type AlertRecipeSlot,
  type AlertVariantProps,
  alertRecipe,
} from "@pisagor/recipes/alert";
import { cn } from "@pisagor/utils";
import { computed, defineComponent, h, type PropType, toValue, type VNodeChild } from "vue";
import type { ClassValue, VariantClassNames } from "../../internal/types";
import { createContext } from "../../internal/utils/create-context";

// #region Types
type AlertClassNames = VariantClassNames<AlertRecipeSlot>;

export interface AlertProps extends AlertVariantProps {
  action?: VNodeChild;
  actionProps?: Record<string, unknown>;
  /**
   * Style recipe. Defaults to `alertRecipe` from `@pisagor/recipes/alert`.
   *
   * @defaultValue alertRecipe
   */
  recipe?: typeof alertRecipe;
  class?: unknown;
  classNames?: AlertClassNames;
  description?: VNodeChild;
  descriptionProps?: Record<string, unknown>;
  icon?: VNodeChild;
  title?: VNodeChild;
  titleProps?: Record<string, unknown>;
}

interface AlertContextValue {
  classNames?: AlertClassNames;
  slots: AlertRecipe;
}
// #endregion

type ArkPart = Parameters<typeof h>[0];

// #region Context
const [provideAlertContext, , useAlertContextRef] = createContext<AlertContextValue>({
  name: "Alert",
});
// #endregion

// #region Parts
export const AlertRoot = defineComponent({
  inheritAttrs: false,
  name: "AlertRoot",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
    classNames: { default: undefined, type: Object as PropType<AlertClassNames> },
    recipe: {
      default: alertRecipe,
      type: Function as PropType<typeof alertRecipe>,
    },
    variant: { default: undefined, type: String as PropType<AlertVariantProps["variant"]> },
  },
  setup(props, { attrs, slots }) {
    const contextValue = computed(() => ({
      classNames: props.classNames,
      slots: props.recipe({ variant: props.variant }),
    }));

    provideAlertContext(contextValue);

    return () =>
      h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: contextValue.value.slots.base({ class: props.class }),
          "data-part": "root",
          "data-scope": "alert",
        },
        slots,
      );
  },
});

export const AlertTitle = defineComponent({
  inheritAttrs: false,
  name: "AlertTitle",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
  },
  setup(props, { attrs, slots }) {
    const contextRef = useAlertContextRef();

    return () => {
      const contextValue = toValue(contextRef);
      if (!contextValue) {
        return null;
      }

      const { classNames, slots: variantSlots } = contextValue;

      return h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: variantSlots.title({ class: cn(props.class, classNames?.title) }),
          "data-part": "title",
          "data-scope": "alert",
        },
        slots,
      );
    };
  },
});

export const AlertDescription = defineComponent({
  inheritAttrs: false,
  name: "AlertDescription",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
  },
  setup(props, { attrs, slots }) {
    const contextRef = useAlertContextRef();

    return () => {
      const contextValue = toValue(contextRef);
      if (!contextValue) {
        return null;
      }

      const { classNames, slots: variantSlots } = contextValue;

      return h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: variantSlots.description({ class: cn(props.class, classNames?.description) }),
          "data-part": "description",
          "data-scope": "alert",
        },
        slots,
      );
    };
  },
});

export const AlertAction = defineComponent({
  inheritAttrs: false,
  name: "AlertAction",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
  },
  setup(props, { attrs, slots }) {
    const contextRef = useAlertContextRef();

    return () => {
      const contextValue = toValue(contextRef);
      if (!contextValue) {
        return null;
      }

      const { classNames, slots: variantSlots } = contextValue;

      return h(
        ark.div as ArkPart,
        {
          ...attrs,
          class: variantSlots.action({ class: cn(props.class, classNames?.action) }),
          "data-part": "action",
          "data-scope": "alert",
        },
        slots,
      );
    };
  },
});

export const AlertShorthand = defineComponent({
  inheritAttrs: false,
  name: "AlertShorthand",
  props: {
    action: { default: undefined, type: [String, Object, Array] as PropType<VNodeChild> },
    actionProps: { default: undefined, type: Object as PropType<Record<string, unknown>> },
    class: { type: [String, Object, Array] as PropType<ClassValue> },
    classNames: { default: undefined, type: Object as PropType<AlertClassNames> },
    description: { default: undefined, type: [String, Object, Array] as PropType<VNodeChild> },
    descriptionProps: { default: undefined, type: Object as PropType<Record<string, unknown>> },
    icon: { default: undefined, type: [String, Object, Array] as PropType<VNodeChild> },
    title: { default: undefined, type: [String, Object, Array] as PropType<VNodeChild> },
    titleProps: { default: undefined, type: Object as PropType<Record<string, unknown>> },
    variant: { default: undefined, type: String as PropType<AlertVariantProps["variant"]> },
  },
  setup(props, { attrs }) {
    return () => {
      const nodes: VNodeChild[] = [];

      if (props.icon !== undefined) {
        nodes.push(props.icon);
      }

      if (props.title !== undefined) {
        nodes.push(h(AlertTitle, props.titleProps, () => props.title));
      }

      if (props.description !== undefined) {
        nodes.push(h(AlertDescription, props.descriptionProps, () => props.description));
      }

      if (props.action !== undefined) {
        nodes.push(h(AlertAction, props.actionProps, () => props.action));
      }

      return h(
        AlertRoot,
        {
          ...attrs,
          class: props.class,
          classNames: props.classNames,
          variant: props.variant,
        },
        () => nodes,
      );
    };
  },
});
// #endregion

import { AlertAction, AlertDescription, AlertRoot, AlertShorthand, AlertTitle } from "./alert";

export type { AlertProps } from "./alert";

export const Alert = Object.assign(AlertShorthand, {
  Action: AlertAction,
  Description: AlertDescription,
  Root: AlertRoot,
  Title: AlertTitle,
});

import { buttonRecipe } from "@pisagor/recipes/button";
import { dialogRecipe } from "@pisagor/recipes/dialog";
import { cn } from "@pisagor/utils";
import { defineComponent, h, type PropType } from "vue";
import type { ClassValue } from "../../internal/types";
import type {
  DialogBodyProps,
  DialogContentProps,
  DialogHeaderProps,
  DialogProps,
} from "../dialog/dialog";
import {
  DialogBody,
  DialogCloseTrigger,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogRoot,
  DialogTitle,
  DialogTrigger,
  useDialog,
} from "../dialog/dialog";

type ArkPart = Parameters<typeof h>[0];

// #region Parts
export const AlertDialogRoot = defineComponent({
  inheritAttrs: false,
  name: "AlertDialogRoot",
  setup(_, { attrs, slots }) {
