  /**
   * Style recipe. Defaults to `drawerRecipe` from `@pisagor/recipes/drawer`.
   *
   * @defaultValue drawerRecipe
   */
  recipe?: typeof drawerRecipe;
}
// #endregion

// #region Context
const [provideDrawerContext, useDrawerLocal] = createContext<DrawerContextValue>({
  name: "DrawerLocal",
  strict: false,
});

function useDrawerSlots() {
  return useDrawerLocal()?.slots ?? drawerRecipe();
}
// #endregion

type ArkPart = Parameters<typeof h>[0];

const SWIPE_DIRECTION_TO_PLACEMENT = {
  down: "down",
  end: "right",
  start: "left",
  up: "up",
} as const;

function drawerTeleport(content: ReturnType<typeof h> | ReturnType<typeof h>[]) {
  return h(Teleport, { to: "body" }, () => content);
}

// #region Parts
export const DrawerRoot = defineComponent({
  inheritAttrs: false,
  name: "DrawerRoot",
  props: {
    recipe: {
      default: drawerRecipe,
      type: Function as PropType<typeof drawerRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    const context = reactive<DrawerContextValue>({
      slots: props.recipe(),
    });
    provideDrawerContext(context);

    return () => h(DrawerPrimitive.Root as ArkPart, { ...attrs }, slots);
  },
});

