                {
                  ...attrs,
                  class: drawerSlots.content({
                    class: props.class,
                    placement: SWIPE_DIRECTION_TO_PLACEMENT[drawerApi.swipeDirection],
                    variant: props.variant,
                  }),
                },
                () => [h(DrawerGrabber), slots.default?.()],
