// #region Types
export interface MarqueeProps {
  orientation?: "horizontal" | "vertical";
  showEdges?: boolean;
  spacing?: string;
  speed?: number;
  items?: VNodeChild[];
  /**
   * Style recipe. Defaults to `marqueeRecipe` from `@pisagor/recipes/marquee`.
   *
   * @defaultValue marqueeRecipe
   */
  recipe?: typeof marqueeRecipe;
  class?: unknown;
}

type ArkPart = Parameters<typeof h>[0];

// #region Parts
export const MarqueeRoot = defineComponent({
  inheritAttrs: false,
  name: "MarqueeRoot",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
    items: { default: undefined, type: Array as PropType<VNodeChild[]> },
    orientation: {
      default: "horizontal",
      type: String as PropType<"horizontal" | "vertical">,
    },
    recipe: {
      default: marqueeRecipe,
      type: Function as PropType<typeof marqueeRecipe>,
    },
    showEdges: { default: true, type: Boolean },
    spacing: { default: "16px", type: String },
    speed: { default: 50, type: Number },
  },
  setup(props, { attrs, slots }) {
    return () => {
      const side = props.orientation === "horizontal" ? "start" : "bottom";
      const items = props.items;
      const variantSlots = props.recipe();

      return h(
        MarqueePrimitive.Root as ArkPart,
        {
          ...attrs,
          class: variantSlots.base({ class: props.class }),
          "data-orientation": props.orientation,
          side,
          spacing: props.spacing,
          speed: props.speed,
        },
        () => [
          slots.default?.(),
          items?.length
            ? h(MarqueeContent, null, () =>
                items.map((item, index) => h(MarqueeItem, { key: index }, () => item)),
              )
            : null,
          props.showEdges
            ? [
                h(MarqueeEdge, {
                  key: "start",
                  side: props.orientation === "horizontal" ? "start" : "top",
                }),
                h(MarqueeEdge, {
                  key: "end",
                  side: props.orientation === "horizontal" ? "end" : "bottom",
                }),
              ]
            : null,
        ],
      );
    };
  },
});

