          readOnly: props.readOnly,
          step: props.step,
        },
        () =>
          slots.default?.() ?? [
            h(
              NumberInputControl as ArkPart,
              { clearable: props.clearable, variant: props.variant },
              () => [
                h(NumberInputDecrementTrigger as ArkPart),
                h(NumberInputInput as ArkPart, {
                  placeholder: props.placeholder,
                  size: props.size,
