import { type ClearableChangeEvent, useClearableInput } from "../../hooks/use-clearable-input";
import type { ClassValue } from "../../internal/types";
import { InputGroup } from "../input-group";
import type { InputGroupButtonProps, InputGroupProps } from "../input-group/input-group-core";

type ArkPart = Parameters<typeof h>[0];

type ClearableInputChangeHandler = (event: ClearableChangeEvent) => void;

// #region Types
export interface PasswordInputProps extends Pick<InputGroupProps, "size" | "variant"> {
  /**
   * Style recipe. Defaults to `passwordInputRecipe` from `@pisagor/recipes/password-input`.
   *
   * @defaultValue passwordInputRecipe
   */
  recipe?: typeof passwordInputRecipe;
  class?: unknown;
  clearButtonProps?: InputGroupButtonProps;
  clearable?: boolean;
  defaultValue?: string;
  defaultVisible?: boolean;
  disabled?: boolean;
  indicatorProps?: Record<string, unknown>;
  invalid?: boolean;
  onChange?: ClearableInputChangeHandler;
  onValueChange?: (value: string) => void;
  onVisibilityChange?: (details: { visible: boolean }) => void;
  placeholder?: string;
  readOnly?: boolean;
  value?: string;
  visibilityTriggerProps?: Record<string, unknown>;
  visible?: boolean;
}
// #endregion

// #region Component
export const PasswordInput = defineComponent({
  inheritAttrs: false,
  name: "PasswordInput",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
    clearable: { default: false, type: Boolean },
    clearButtonProps: { default: undefined, type: Object as PropType<InputGroupButtonProps> },
    defaultValue: { default: undefined, type: String },
    defaultVisible: { default: undefined, type: Boolean },
    disabled: { default: undefined, type: Boolean },
    indicatorProps: { default: undefined, type: Object as PropType<Record<string, unknown>> },
    invalid: { default: undefined, type: Boolean },
    onChange: { default: undefined, type: Function as PropType<PasswordInputProps["onChange"]> },
    onValueChange: {
      default: undefined,
      type: Function as PropType<PasswordInputProps["onValueChange"]>,
    },
    onVisibilityChange: {
      default: undefined,
      type: Function as PropType<PasswordInputProps["onVisibilityChange"]>,
    },
    placeholder: { default: undefined, type: String },
    readOnly: { default: undefined, type: Boolean },
    recipe: {
      default: passwordInputRecipe,
      type: Function as PropType<typeof passwordInputRecipe>,
    },
    size: { default: "md", type: String as PropType<PasswordInputProps["size"]> },
    value: { default: undefined, type: String },
    variant: { default: undefined, type: String as PropType<PasswordInputProps["variant"]> },
    visibilityTriggerProps: {
      default: undefined,
      type: Object as PropType<Record<string, unknown>>,
    },
    visible: { default: undefined, type: Boolean },
  },
  setup(props, { attrs, slots }) {
    const { canClear, handleChange, handleClear, inputRef } = useClearableInput({
      clearable: () => props.clearable,
      defaultValue: props.defaultValue,
      disabled: () => props.disabled,
      onChange: props.onChange,
      onValueChange: props.onValueChange,
      readOnly: () => props.readOnly,
      value: () => props.value,
    });

    return () => {
      const { onClick: onClearClick, ...restClearButtonProps } = props.clearButtonProps ?? {};
      const { fallback, ...restIndicatorProps } = props.indicatorProps ?? {};
      const variantSlots = props.recipe();

      return h(
        PasswordInputPrimitive.Root as ArkPart,
        {
          class: variantSlots.base({ class: props.class }),
          "data-size": props.size,
          defaultVisible: props.defaultVisible,
          invalid: props.invalid,
          onVisibilityChange: props.onVisibilityChange,
          visible: props.visible,
        },
        () =>
          h(PasswordInputPrimitive.Control as ArkPart, { asChild: true }, () =>
            h(
              InputGroup as ArkPart,
              {
                class: variantSlots.control(),
                "data-clearable": props.clearable || undefined,
                size: props.size,
                variant: props.variant,
              },
              () => [
                h(
                  PasswordInputPrimitive.Input as ArkPart,
                  {
                    asChild: true,
                    defaultValue: props.defaultValue,
                    disabled: props.disabled,
                    onInput: handleChange,
                    placeholder: props.placeholder,
                    readOnly: props.readOnly,
                    ref: inputRef,
                    value: props.value,
                    ...(attrs as object),
                  },
                  () => h(InputGroup.Input as ArkPart, { clearable: false }),
                ),
                canClear.value
                  ? h(
                      InputGroup.Addon as ArkPart,
                      { align: "inline-end", class: variantSlots.clearAddon() },
                      () =>
                        h(
                          InputGroup.Button as ArkPart,
                          {
                            ...restClearButtonProps,
                            "aria-label": "Clear",
                            "data-part": "clear-trigger",
                            "data-scope": "password-input",
                            onClick: (event: MouseEvent) => {
                              handleClear();
                              onClearClick?.(event);
                            },
                            size: "icon-xs",
                            type: "button",
                            variant: "ghost",
                          },
                          () => slots.clearButton?.() ?? h(PhX),
                        ),
                    )
                  : null,
                h(InputGroup.Addon as ArkPart, { align: "inline-end" }, () =>
                  h(
                    PasswordInputPrimitive.VisibilityTrigger as ArkPart,
                    {
                      asChild: true,
                      ...props.visibilityTriggerProps,
                    },
                    () =>
                      h(
                        InputGroup.Button as ArkPart,
                        {
                          "aria-label": "Toggle password visibility",
                          size: "icon-xs",
                          type: "button",
                          variant: "ghost",
                        },
                        () =>
                          h(
                            PasswordInputPrimitive.Indicator as ArkPart,
                            {
                              ...restIndicatorProps,
                            },
                            {
                              default: () => slots.indicator?.() ?? h(PhEye),
                              fallback: () => fallback ?? h(PhEyeSlash),
                            },
                          ),
                      ),
                  ),
                ),
              ],
            ),
          ),
      );
    };
  },
});
// #endregion

import { PhGlobe } from "@phosphor-icons/vue";
import { phoneInputRecipe } from "@pisagor/recipes/phone-input";
import { cn } from "@pisagor/utils";

type FormControlVariant = "primary" | "secondary";

type ClassValue = Parameters<typeof cn>[0];

import { defineComponent, h, type PropType, ref } from "vue";
import type { InputProps } from "../components/input";
import { InputGroup } from "../components/input-group";
import { InputGroupRoot } from "../components/input-group/input-group-core";

type ArkPart = Parameters<typeof h>[0];

export interface PhoneInputProps {
  /**
   * Style recipe. Defaults to `phoneInputRecipe` from `@pisagor/recipes/phone-input`.
   *
   * @defaultValue phoneInputRecipe
   */
  recipe?: typeof phoneInputRecipe;
  class?: ClassValue;
  size?: InputProps["size"];
  variant?: FormControlVariant;
  invalid?: boolean;
  disabled?: boolean;
  readOnly?: boolean;
  value?: string;
  defaultValue?: string;
  onChange?: (value: string) => void;
  defaultCountry?: string;
  inputProps?: Omit<
    InputProps,
    "className" | "onChange" | "size" | "type" | "value" | "defaultValue"
  >;
  popupProps?: unknown;
}

export const PhoneInput = defineComponent({
  inheritAttrs: false,
  name: "PhoneInput",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
    defaultCountry: { default: undefined, type: String as PropType<string | undefined> },
    defaultValue: { default: undefined, type: String as PropType<string | undefined> },
    disabled: { default: undefined, type: Boolean },
    inputProps: {
      default: undefined,
      type: Object as PropType<PhoneInputProps["inputProps"] | undefined>,
    },
    invalid: { default: undefined, type: Boolean },
    onChange: { default: undefined, type: Function as PropType<PhoneInputProps["onChange"]> },
    readOnly: { default: undefined, type: Boolean },
    recipe: {
      default: phoneInputRecipe,
      type: Function as PropType<typeof phoneInputRecipe>,
    },
    size: { default: undefined, type: String as PropType<PhoneInputProps["size"]> },
    value: { default: undefined, type: String as PropType<string | undefined> },
    variant: { default: undefined, type: String as PropType<FormControlVariant | undefined> },
  },
  setup(props, { attrs }) {
    return () => {
      const slots = props.recipe({ size: props.size ?? "md" });
      const isControlled = props.value !== undefined;
      const internalValue = ref(props.defaultValue ?? "");
      const value = isControlled ? (props.value ?? "") : internalValue.value;

      const handleValueChange = (next: string) => {
        if (!isControlled) internalValue.value = next;
        props.onChange?.(next);
      };

      return h(
        InputGroupRoot as ArkPart,
        {
          ...attrs,
          class: cn(props.class, (attrs as { class?: ClassValue }).class),
          "data-part": "root",
          "data-scope": "phone-input",
          role: "group",
          size: props.size,
          variant: props.variant,
        },
        () => [
          h(
            InputGroup.Addon as ArkPart,
            {
              align: "inline-start",
              class: slots.countryTrigger({
                class: cn((attrs as { class?: ClassValue }).class),
              }),
              "data-part": "country-trigger",
              "data-scope": "phone-input",
            },
            () => h("span", { class: slots.flag({ class: slots.flagIcon() }) }, () => h(PhGlobe)),
          ),
          h(
            InputGroup.Input as ArkPart,
            {
              ...props.inputProps,
              ...attrs,
              "aria-invalid": props.invalid || undefined,
              class: slots.input({
                class: cn(
                  (props.inputProps as unknown as { class?: ClassValue } | undefined)?.class,
                  (attrs as { class?: ClassValue }).class,
                ),
              }),
              "data-invalid": props.invalid || undefined,
              disabled: props.disabled,
              onValueChange: handleValueChange,
              readOnly: props.readOnly,
              type: "tel",
              value,
            } as unknown as Parameters<typeof h>[1],
          ),
        ],
      );
    };
  },
});

import { Popover as PopoverPrimitive } from "@ark-ui/vue/popover";
import { popoverRecipe } from "@pisagor/recipes/popover";
import { type CSSProperties, defineComponent, h, type PropType, Teleport } from "vue";
