type ArkPart = Parameters<typeof h>[0];

const SKIP_NAV_ID = "skip-nav-content";

// #region Parts
export const SkipNavLink = defineComponent({
  inheritAttrs: false,
  name: "SkipNavLink",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
    id: { default: SKIP_NAV_ID, type: String },
    recipe: {
      default: skipNavRecipe,
      type: Function as PropType<typeof skipNavRecipe>,
    },
