  setup(props, { attrs, slots }) {
    const variantSlots = props.recipe();

    return () =>
      h(
        ark.a as ArkPart,
        {
          ...attrs,
          class: cn(variantSlots.link(), props.class, attrs.class),
          "data-part": "link",
          "data-scope": "skip-nav",
          href: `#${props.id}`,
        },
        slots.default ?? (() => "Skip to content"),
      );
  },
});

