import { Slider as SliderPrimitive } from "@ark-ui/vue/slider";
import { sliderRecipe } from "@pisagor/recipes/slider";
import { defineComponent, h, type PropType, type VNodeChild } from "vue";
import type { ClassValue } from "../../internal/types";
import { useFormControlSurface } from "../surface/use-form-control-surface";

type FormControlVariant = "primary" | "secondary";

type ArkPart = Parameters<typeof h>[0];

export interface SliderProps {
  /**
   * Style recipe. Defaults to `sliderRecipe` from `@pisagor/recipes/slider`.
   *
   * @defaultValue sliderRecipe
   */
  recipe?: typeof sliderRecipe;
  class?: unknown;
  defaultValue?: number[];
  disabled?: boolean;
  label?: VNodeChild;
  markerInterval?: number;
  markerLabels?: string[];
  max?: number;
  min?: number;
  onValueChange?: (value: number[]) => void;
  showMarkers?: boolean;
  showValue?: boolean;
  step?: number;
  tabIndex?: number;
  value?: number[];
  variant?: FormControlVariant;
}

export const Slider = defineComponent({
  inheritAttrs: false,
  name: "PisagorSlider",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
    defaultValue: { default: undefined, type: Array as PropType<number[] | undefined> },
    disabled: { default: undefined, type: Boolean },
    label: { default: undefined, type: [String, Object, Array] as PropType<VNodeChild> },
    markerInterval: { default: 1, type: Number },
    markerLabels: { default: undefined, type: Array as PropType<string[] | undefined> },
    max: { default: 100, type: Number },
    min: { default: 0, type: Number },
    onValueChange: { default: undefined, type: Function as PropType<SliderProps["onValueChange"]> },
    recipe: {
      default: sliderRecipe,
      type: Function as PropType<typeof sliderRecipe>,
    },
    showMarkers: { default: false, type: Boolean },
    showValue: { default: false, type: Boolean },
    step: { default: undefined, type: Number },
    tabIndex: { default: undefined, type: Number },
    value: { default: undefined, type: Array as PropType<number[] | undefined> },
    variant: { default: undefined, type: String as PropType<FormControlVariant | undefined> },
  },
  setup(props, { attrs, slots }) {
    const surfaceVariant = useFormControlSurface();

    return () => {
      const resolved = {
        surfaceVariant,
        variant: props.variant ?? ("primary" as FormControlVariant),
      };
      const trackShellProps = { "data-variant": resolved.variant };

      const variantSlots = props.recipe();

      const thumbShadowClass = resolved.variant === "secondary" ? "shadow-none" : undefined;
      const trackVariantClass = resolved.variant === "secondary" ? "bg-muted/40" : "bg-input/64";

      const _values = Array.isArray(props.value)
        ? props.value
        : Array.isArray(props.defaultValue)
          ? props.defaultValue
          : [props.min, props.max];

      return h(
        SliderPrimitive.Root as ArkPart,
        {
          ...attrs,
          ...trackShellProps,
          class: variantSlots.base({ class: props.class }),
          defaultValue: props.defaultValue,
          disabled: props.disabled,
          max: props.max,
          min: props.min,
          modelValue: props.value,
          onValueChange: props.onValueChange
            ? (details: { value: number[] }) => props.onValueChange?.(details.value)
            : undefined,
          step: props.step,
        },
        () => [
          (props.label !== undefined || props.showValue) && [
            h("div", { class: variantSlots.header() }, () => [
              props.label !== undefined
                ? h(SliderPrimitive.Label as ArkPart, {}, () => props.label)
                : null,
              props.showValue
                ? h(
                    SliderPrimitive.ValueText as ArkPart,
                    {
                      ...(attrs as object),
                      class: variantSlots.value({ class: "tabular-nums" }),
                    },
                    undefined,
                  )
                : null,
            ]),
          ],
          slots.default?.(),
          h(SliderPrimitive.Control as ArkPart, { class: variantSlots.control() }, () =>
            h(
              SliderPrimitive.Track as ArkPart,
              {
                class: variantSlots.track({ class: trackVariantClass }),
              },
              () => [
                h(SliderPrimitive.Range as ArkPart, {
                  class: variantSlots.range(),
                }),
                ..._values.map((_, index) =>
                  h(
                    SliderPrimitive.Thumb as ArkPart,
                    {
                      class: variantSlots.thumb({ class: thumbShadowClass }),
                      index,
                      tabIndex: props.tabIndex ?? undefined,
                    },
                    () => h(SliderPrimitive.HiddenInput as ArkPart, {}),
                  ),
                ),
              ],
            ),
          ),
          props.showMarkers
            ? h(SliderPrimitive.MarkerGroup as ArkPart, { class: variantSlots.markerGroup() }, () =>
                Array.from({ length: props.max + 1 }, (_, index) =>
                  h(
                    SliderPrimitive.Marker as ArkPart,
                    {
                      class: variantSlots.marker(),
                      "data-interval": index % props.markerInterval === 0 ? undefined : "",
                      key: String(index),
                      value: index,
                    },
                    () => [
                      h("span", { class: variantSlots.markerTick() }),
                      h(
                        "span",
                        { class: variantSlots.markerLabel() },
                        () => props.markerLabels?.[index] ?? String(index),
                      ),
                    ],
                  ),
                ),
              )
            : null,
        ],
      );
    };
  },
});

import { ark } from "@ark-ui/vue/factory";
import { PhDotsSixVertical } from "@phosphor-icons/vue";
import {
  type SortableItemRecipe,
  sortableItemRecipe,
  sortableRecipe,
} from "@pisagor/recipes/sortable";
import { cn } from "@pisagor/utils";
import {
  defineComponent,
  h,
  onBeforeUnmount,
  onMounted,
  type PropType,
  reactive,
  ref,
  watchEffect,
} from "vue";
import type { ClassValue } from "../../internal/types";
import { createContext } from "../../internal/utils/create-context";

// #region Types
type SortableOrientation = "vertical" | "horizontal";

interface SortableContextValue {
  activeId: string | null;
  disabled: boolean;
  endDrag: () => void;
  getItemProps: (id: string) => Record<string, unknown>;
  hasHandle: (id: string) => boolean;
  moveItem: (id: string, delta: -1 | 1) => void;
  orientation: SortableOrientation;
  registerHandle: (id: string) => void;
  startDrag: (id: string, event: DragEvent) => void;
  unregisterHandle: (id: string) => void;
}

interface SortableItemContextValue {
  id: string;
  isDragging: boolean;
  slots: SortableItemRecipe;
}

export interface SortableRootProps {
  items: string[];
  onValueChange?: (items: string[]) => void;
  orientation?: SortableOrientation;
  disabled?: boolean;
  /**
   * Style recipe. Defaults to `sortableRecipe` from `@pisagor/recipes/sortable`.
   *
   * @defaultValue sortableRecipe
   */
  recipe?: typeof sortableRecipe;
  class?: unknown;
}

export interface SortableItemProps {
  value: string;
  /**
   * Style recipe. Defaults to `sortableItemRecipe` from `@pisagor/recipes/sortable-item`.
   *
   * @defaultValue sortableItemRecipe
   */
  itemRecipe?: typeof sortableItemRecipe;
  class?: unknown;
}

export interface SortableHandleProps {
  class?: unknown;
}
// #endregion

// #region Context
const [provideSortableContext, useSortableContext] = createContext<SortableContextValue>({
  name: "Sortable",
});
const [provideSortableItemContext, useSortableItemContext] =
  createContext<SortableItemContextValue>({
    name: "SortableItem",
  });
// #endregion

// #region Helpers
function reorder(list: string[], from: number, to: number) {
  if (from === to || from < 0 || to < 0) return list;
  if (from >= list.length || to >= list.length) return list;

  const next = [...list];
  const moved = next.splice(from, 1)[0];
  if (moved === undefined) return list;
  next.splice(to, 0, moved);
  return next;
}

export function useSortable() {
  return useSortableContext();
}
// #endregion

// #region Parts
type ArkPart = Parameters<typeof h>[0];

export const SortableRoot = defineComponent({
  inheritAttrs: false,
  name: "SortableRoot",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
    disabled: { default: false, type: Boolean },
    items: { required: true, type: Array as PropType<string[]> },
    onValueChange: { default: undefined, type: Function as PropType<(items: string[]) => void> },
    orientation: {
      default: "vertical",
      type: String as PropType<SortableOrientation>,
    },
    recipe: {
      default: sortableRecipe,
      type: Function as PropType<typeof sortableRecipe>,
    },
  },
  setup(props, { attrs, slots }) {
    const activeId = ref<string | null>(null);
    const overId = ref<string | null>(null);
    const handleIds = ref<Set<string>>(new Set());
    const activeIdRef = ref<string | null>(null);
    const itemsRef = ref(props.items);
    watchEffect(() => {
      itemsRef.value = props.items;
    });

    const hasHandle = (id: string) => handleIds.value.has(id);

    const registerHandle = (id: string) => {
      if (handleIds.value.has(id)) return;
      const next = new Set(handleIds.value);
      next.add(id);
      handleIds.value = next;
    };

    const unregisterHandle = (id: string) => {
      if (!handleIds.value.has(id)) return;
      const next = new Set(handleIds.value);
      next.delete(id);
      handleIds.value = next;
    };

    const startDrag = (id: string, event: DragEvent) => {
      if (!event.dataTransfer) return;
      event.dataTransfer.effectAllowed = "move";
      event.dataTransfer.setData("text/plain", id);
      activeIdRef.value = id;
      activeId.value = id;
    };

    const endDrag = () => {
      activeIdRef.value = null;
      activeId.value = null;
      overId.value = null;
    };

    const commitReorder = (fromId: string, toId: string) => {
      const current = itemsRef.value;
      const from = current.indexOf(fromId);
      const to = current.indexOf(toId);
      if (from === -1 || to === -1 || from === to) return;
      props.onValueChange?.(reorder(current, from, to));
    };

    const moveItem = (id: string, delta: -1 | 1) => {
      if (props.disabled) return;
      const current = itemsRef.value;
      const index = current.indexOf(id);
      const targetIndex = index + delta;
      if (index === -1 || targetIndex < 0 || targetIndex >= current.length) return;
      props.onValueChange?.(reorder(current, index, targetIndex));
    };

    const getItemProps = (id: string) => {
      const itemHasHandle = hasHandle(id);

      return {
        "aria-disabled": props.disabled || undefined,
        "data-dragging": activeId.value === id ? "true" : undefined,
        "data-drop-target": overId.value === id && activeId.value !== id ? "true" : undefined,
        draggable: !props.disabled && !itemHasHandle,
        onDragEnd: () => {
          endDrag();
        },
        onDragEnter: (event: DragEvent) => {
          event.preventDefault();
          const draggingId = activeIdRef.value;
          if (draggingId && draggingId !== id) {
            overId.value = id;
          }
        },
        onDragLeave: (event: DragEvent) => {
          const related = event.relatedTarget as Node | null;
          if (related && event.currentTarget && (event.currentTarget as Node).contains(related)) {
            return;
          }
          overId.value = overId.value === id ? null : overId.value;
        },
        onDragOver: (event: DragEvent) => {
          event.preventDefault();
          if (event.dataTransfer) event.dataTransfer.dropEffect = "move";
          const draggingId = activeIdRef.value;
          if (draggingId && draggingId !== id) {
            overId.value = id;
          }
        },
        onDragStart: (event: DragEvent) => {
          if (props.disabled || hasHandle(id)) {
            event.preventDefault();
            return;
          }
          startDrag(id, event);
        },
        onDrop: (event: DragEvent) => {
          event.preventDefault();
          event.stopPropagation();
          const fromId = event.dataTransfer?.getData("text/plain") || activeIdRef.value;
          if (fromId) commitReorder(fromId, id);
          endDrag();
        },
        onKeyDown: (event: KeyboardEvent) => {
          if (props.disabled) return;
          const movePrev =
            props.orientation === "vertical" ? event.key === "ArrowUp" : event.key === "ArrowLeft";
          const moveNext =
            props.orientation === "vertical"
              ? event.key === "ArrowDown"
              : event.key === "ArrowRight";
          if (!(event.altKey && (movePrev || moveNext))) return;
          event.preventDefault();
          moveItem(id, movePrev ? -1 : 1);
        },
        tabIndex: props.disabled || itemHasHandle ? -1 : 0,
      };
    };

    const contextValue = reactive<SortableContextValue>({
      activeId: null,
      disabled: props.disabled,
      endDrag,
      getItemProps,
      hasHandle,
      moveItem,
      orientation: props.orientation,
      registerHandle,
      startDrag,
      unregisterHandle,
    });

    watchEffect(() => {
      contextValue.activeId = activeId.value;
      contextValue.disabled = props.disabled;
      contextValue.orientation = props.orientation;
    });

    provideSortableContext(contextValue);

    return () =>
      h(
        ark.div as unknown as ArkPart,
        {
          ...attrs,
          class: cn(props.recipe({ orientation: props.orientation }), props.class, attrs.class),
          "data-orientation": props.orientation,
          "data-part": "root",
          "data-scope": "sortable",
          role: "list",
        },
        () => slots.default?.(),
      );
  },
});

export const SortableItem = defineComponent({
  inheritAttrs: false,
  name: "SortableItem",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
    itemRecipe: {
      default: sortableItemRecipe,
      type: Function as PropType<typeof sortableItemRecipe>,
    },
    value: { required: true, type: String },
  },
  setup(props, { attrs, slots }) {
    const sortable = useSortableContext();
    if (!sortable) {
      return () => null;
    }

    const itemSlots = props.itemRecipe();
    const itemContext = reactive<SortableItemContextValue>({
      id: props.value,
      isDragging: false,
      slots: itemSlots,
    });

    provideSortableItemContext(itemContext);

    return () => {
      itemContext.isDragging = sortable.activeId === props.value;
      const itemProps = sortable.getItemProps(props.value);

      return h(
        ark.div as unknown as ArkPart,
        {
          ...attrs,
          ...itemProps,
          class: itemSlots.base({ class: cn(props.class, attrs.class) }),
          "data-part": "item",
          "data-scope": "sortable",
          role: "listitem",
        },
        () => slots.default?.(),
      );
    };
  },
});

export const SortableHandle = defineComponent({
  inheritAttrs: false,
  name: "SortableHandle",
  props: {
    ariaLabel: { default: undefined, type: String },
    class: { type: [String, Object, Array] as PropType<ClassValue> },
  },
  setup(props, { attrs, slots }) {
    const itemContext = useSortableItemContext();
    const sortable = useSortableContext();

    if (!itemContext || !sortable) {
      return () => null;
    }

    onMounted(() => {
      sortable.registerHandle(itemContext.id);
    });

    onBeforeUnmount(() => {
      sortable.unregisterHandle(itemContext.id);
    });

    return () =>
      h(
        ark.div as unknown as ArkPart,
        {
          ...attrs,
          "aria-disabled": sortable.disabled || undefined,
          "aria-label":
            (attrs["aria-label"] as string | undefined) ?? props.ariaLabel ?? "Drag to reorder",
          class: itemContext.slots.handle({
            class: cn(
              sortable.disabled && "pointer-events-none opacity-50",
              props.class,
              attrs.class,
            ),
          }),
          "data-part": "handle",
          "data-scope": "sortable",
          draggable: !sortable.disabled,
          onDragEnd: () => {
            sortable.endDrag();
          },
          onDragStart: (event: DragEvent) => {
            if (sortable.disabled) {
              event.preventDefault();
              return;
            }

            event.stopPropagation();
            sortable.startDrag(itemContext.id, event);
          },
          onKeyDown: (event: KeyboardEvent) => {
            if (sortable.disabled) return;

            const movePrev =
              sortable.orientation === "vertical"
                ? event.key === "ArrowUp"
                : event.key === "ArrowLeft";
            const moveNext =
              sortable.orientation === "vertical"
                ? event.key === "ArrowDown"
                : event.key === "ArrowRight";

            if (!(event.altKey && (movePrev || moveNext))) return;
            event.preventDefault();
            sortable.moveItem(itemContext.id, movePrev ? -1 : 1);
          },
          role: "button",
          tabIndex: sortable.disabled ? -1 : 0,
        },
        () => slots.default?.() ?? h(PhDotsSixVertical),
      );
  },
});

export const SortableItemContent = defineComponent({
  inheritAttrs: false,
  name: "SortableItemContent",
  props: {
    class: { type: [String, Object, Array] as PropType<ClassValue> },
  },
