    if (!itemContext) {
      return () => null;
    }

    return () =>
      h(
        ark.div as unknown as ArkPart,
        {
          ...attrs,
          class: itemContext.slots.content({ class: cn(props.class, attrs.class) }),
          "data-part": "item-content",
          "data-scope": "sortable",
        },
        slots,
      );
  },
});
