              : null,
          ]),
        );
      }

      if (props.actions !== undefined) {
        nodes.push(h(ToolbarActions, props.actionsProps, () => props.actions));
      }

      return h(
        ToolbarRoot,
        {
          ...attrs,
          class: props.class,
          classNames: props.classNames,
