import { Tooltip as TooltipPrimitive } from "@ark-ui/vue/tooltip";
import { type TooltipRecipeSlot, tooltipRecipe } from "@pisagor/recipes/tooltip";
import { defineComponent, h, type PropType, Teleport, type VNodeChild } from "vue";
import type { VariantClassNames } from "../../internal/types";

// #region Types
export type TooltipTriggerHandle = (props: Record<string, unknown>) => VNodeChild;

type TooltipClassNames = VariantClassNames<TooltipRecipeSlot>;

export interface TooltipProps {
  arrowProps?: Record<string, unknown>;
  children: VNodeChild | TooltipTriggerHandle;
  /**
   * Style recipe. Defaults to `tooltipRecipe` from `@pisagor/recipes/tooltip`.
   *
   * @defaultValue tooltipRecipe
   */
  recipe?: typeof tooltipRecipe;
  classNames?: TooltipClassNames;
  closeDelay?: number;
  content: VNodeChild;
  contentProps?: Record<string, unknown>;
  lazyMount?: boolean;
  openDelay?: number;
  positionerProps?: Record<string, unknown>;
  positioning?: Record<string, unknown>;
  triggerProps?: Record<string, unknown>;
  unmountOnExit?: boolean;
}
// #endregion

type ArkPart = Parameters<typeof h>[0];

function isTriggerHandle(
  children: VNodeChild | TooltipTriggerHandle,
): children is TooltipTriggerHandle {
  return typeof children === "function";
}

// #region Component
export const Tooltip = defineComponent({
  inheritAttrs: false,
  name: "PisagorTooltip",
  props: {
    arrowProps: { default: undefined, type: Object as PropType<Record<string, unknown>> },
    children: {
      required: true,
      type: [Object, Function, String, Array] as PropType<VNodeChild | TooltipTriggerHandle>,
    },
    classNames: { default: undefined, type: Object as PropType<TooltipClassNames> },
    closeDelay: { default: 150, type: Number },
    content: { required: true, type: [Object, String, Array] as PropType<VNodeChild> },
    contentProps: { default: undefined, type: Object as PropType<Record<string, unknown>> },
    lazyMount: { default: true, type: Boolean },
    openDelay: { default: 400, type: Number },
    positionerProps: { default: undefined, type: Object as PropType<Record<string, unknown>> },
    positioning: {
      default: () => ({ placement: "top" }),
      type: Object as PropType<Record<string, unknown>>,
    },
    recipe: {
      default: tooltipRecipe,
      type: Function as PropType<typeof tooltipRecipe>,
    },
    triggerProps: { default: undefined, type: Object as PropType<Record<string, unknown>> },
    unmountOnExit: { default: true, type: Boolean },
  },
  setup(props, { attrs }) {
    return () => {
      const slots = props.recipe();
      const trigger = isTriggerHandle(props.children)
        ? h(TooltipPrimitive.Context as ArkPart, null, {
            default: (api: { getTriggerProps: () => Record<string, unknown> }) =>
              (props.children as TooltipTriggerHandle)(api.getTriggerProps()),
          })
        : h(
            TooltipPrimitive.Trigger as ArkPart,
            {
              ...props.triggerProps,
              asChild: true,
            },
            () => props.children,
          );

      return h(
        TooltipPrimitive.Root as ArkPart,
        {
          ...attrs,
          closeDelay: props.closeDelay,
          lazyMount: props.lazyMount,
          openDelay: props.openDelay,
          positioning: props.positioning,
          unmountOnExit: props.unmountOnExit,
        },
        () => [
          trigger,
          h(Teleport, { to: "body" }, () =>
            h(TooltipPrimitive.Positioner as ArkPart, { ...props.positionerProps }, () =>
              h(
                TooltipPrimitive.Content as ArkPart,
                {
                  ...props.contentProps,
                  class: slots.content({ class: props.classNames?.content }),
                },
                () => [
                  h(
                    TooltipPrimitive.Arrow as ArkPart,
                    {
                      ...props.arrowProps,
                      class: slots.arrow({ class: props.classNames?.arrow }),
                    },
                    () => h(TooltipPrimitive.ArrowTip as ArkPart),
                  ),
                  props.content,
                ],
              ),
            ),
          ),
        ],
      );
    };
  },
});
// #endregion

import { ark } from "@ark-ui/vue/factory";
import {
  Tour as TourPrimitive,
  type TourStepDetails,
  type UseTourReturn,
  useTour,
} from "@ark-ui/vue/tour";
import { PhCaretLeft, PhCaretRight, PhX } from "@phosphor-icons/vue";
import { dialogRecipe } from "@pisagor/recipes/dialog";
import { type TourRecipe, tourRecipe } from "@pisagor/recipes/tour";
import { cn } from "@pisagor/utils";
import {
  computed,
  defineComponent,
  h,
  type PropType,
  reactive,
  ref,
  Teleport,
  toValue,
  type UnwrapRef,
  watchEffect,
} from "vue";
import { createContext } from "../../internal/utils/create-context";
import { Button } from "../button";
import { DialogBody, DialogFooter, DialogHeader } from "../dialog";

type ArkPart = Parameters<typeof h>[0];
type ClassValue = Parameters<typeof cn>[0];

// #region Types
export type TourStepType = TourStepDetails;

interface TourContextProps {
  /** The function to start the tour */
  handleStart: () => void;
  /** Slot class recipes from `tourRecipe`. */
  slots: TourRecipe;
  /** The tour instance */
  tour: UnwrapRef<UseTourReturn>;
}

export interface TourRootProps {
  /** Whether to enable arrow key navigation between steps */
  keyboardNavigation?: boolean;
  /**
   * Whether to lazily mount the content
   *
   * @defaultValue true
   */
  lazyMount?: boolean;
  /** Called when the tour status changes */
  onStatusChange?: (details: { status: string }) => void;
  /** Called when the current step changes */
  onStepChange?: (details: { stepId: string | null }) => void;
  /**
   * The steps to display in the tour
   *
   * @defaultValue []
   */
  steps?: TourStepDetails[];
  /**
   * Whether to unmount the content when the tour is closed
   *
   * @defaultValue true
   */
  unmountOnExit?: boolean;
}

export interface TourBackdropProps {
  /**
   * Style recipe. Defaults to `dialogRecipe` from `@pisagor/recipes/dialog`.
   *
   * @defaultValue dialogRecipe
   */
  dialogRecipe?: typeof dialogRecipe;
  /**
   * Style recipe. Defaults to `tourRecipe` from `@pisagor/recipes/tour`.
   *
   * @defaultValue tourRecipe
   */
  recipe?: typeof tourRecipe;
  class?: unknown;
}
// #endregion

// #region Context
const [provideTourContext, , useTourContextRef] = createContext<TourContextProps>({
  name: "Tour",
});

export { useTourContextRef as useTourContext };
// #endregion

// #region Parts
export const TourRoot = defineComponent({
  inheritAttrs: false,
  name: "TourRoot",
  props: {
    keyboardNavigation: { default: undefined, type: Boolean },
    lazyMount: { default: true, type: Boolean },
    onStatusChange: {
      default: undefined,
      type: Function as PropType<TourRootProps["onStatusChange"]>,
    },
    onStepChange: {
      default: undefined,
      type: Function as PropType<TourRootProps["onStepChange"]>,
    },
    recipe: {
      default: tourRecipe,
      type: Function as PropType<typeof tourRecipe>,
    },
    steps: { default: () => [], type: Array as PropType<TourStepDetails[]> },
    unmountOnExit: { default: true, type: Boolean },
  },
  setup(props, { attrs, slots }) {
    const isStarted = ref(false);

    const tour = useTour(
      computed(() => ({
        keyboardNavigation: props.keyboardNavigation,
        onStatusChange: props.onStatusChange,
        onStepChange: props.onStepChange,
        steps: props.steps,
      })),
    );

    watchEffect((onCleanup) => {
      document.body.classList.toggle("relative", isStarted.value);
      onCleanup(() => document.body.classList.remove("relative"));
    });

    const handleStart = () => {
      isStarted.value = true;
      tour.value.start();
    };

    const context = reactive({
      handleStart,
      slots: props.recipe(),
      tour,
    });

    provideTourContext(context);

    return () =>
      h(
        TourPrimitive.Root as ArkPart,
        {
          ...attrs,
          lazyMount: props.lazyMount,
          tour: tour.value,
          unmountOnExit: props.unmountOnExit,
        },
        slots,
      );
  },
});

export const TourTrigger = defineComponent({
  inheritAttrs: false,
  name: "Tour.Trigger",
  setup(_, { attrs, slots }) {
    return () => {
      const ctx = toValue(useTourContextRef());
      if (!ctx) return null;
      const { handleStart } = ctx;
      const onClick = attrs.onClick as ((event: MouseEvent) => void) | undefined;

      const handleClick = (event: MouseEvent) => {
        onClick?.(event);
        handleStart();
      };

      return h(
        ark.button as ArkPart,
        {
          ...attrs,
